/*
 * A155585  a(n) = 2^n*E(n, 1) where E(n, x) are the Euler polynomials.
 * https://oeis.org/A155585
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  sign, easy
 * Formula:   a(n) = 2^n * E_n(1) (Euler polynomial value) For n even >0,
 *            a(n)=0; for odd n=2m+1, a(n)=(-1)^m * T_m, where T_m are tangent
 *            numbers = Euler zigzag numbers A000111[2m+1]. A000111 is
 *            generated by the recurrence E[0] = 1, E[1] = 1, for n>=2: E[n] =
 *            (1/2) * Σ_{k=0}^{n-1} C(n-1,k) * E[k] * E[n-1-k]
 * Range:     i8 n <= 6, i16 n <= 10, i32 n <= 14, i64 n <= 24, i128 n <= 38,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>

static seq_t *A = NULL;      /* array of Euler zigzag values E[n] */
static idx_t A_size = 0;     /* next index to compute (size of filled part) */
static idx_t A_cap   = 0;    /* allocated capacity */

/* ensure that E[n] is known for all n <= N */
static void compute_A_up_to(idx_t N)
{
    /* grow storage if necessary */
    if (N + 1 > A_cap) {
        size_t new_cap = (size_t)(N + 1);
        seq_t *newA = (seq_t *)realloc(A, new_cap * sizeof(seq_t));
        if (!newA) exit(EXIT_FAILURE);
        A = newA;
        A_cap = new_cap;
    }

    /* initialise base cases */
    if (A_size == 0) {
        A[0] = (seq_t)1;
        if (N >= 1) A[1] = (seq_t)1;
        A_size = (N >= 1) ? 2 : 1;
    }

    /* compute remaining terms up to N */
    for (idx_t n = A_size; n <= N; ++n) {
        if (n == 0) { A[0] = (seq_t)1; continue; }
        if (n == 1) { A[1] = (seq_t)1; continue; }

        seq_t sum  = (seq_t)0;
        seq_t binom = (seq_t)1;          /* binom(n-1,0) */

        for (idx_t k = 0; k <= n - 1; ++k) {
            /* product = binom * A[k] * A[n-1-k] */
            seq_t prod = binom * A[k];
            prod = prod * A[n - 1 - k];
            sum += prod;

            /* update binom for next k: C(n-1,k+1) = C(n-1,k) * (n-1-k)/(k+1) */
            if (k < n - 1) {
                seq_t num = (seq_t)(n - 1 - k);
                seq_t den = (seq_t)(k + 1);
                binom = (binom * num) / den;
            }
        }

        /* for n >= 2, sum is even */
        A[n] = sum / (seq_t)2;
    }
    A_size = N + 1;
}

seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)1;                /* a(0) = 1 */

    if ((n & (idx_t)1ULL) == 0)                 /* even index */
        return (seq_t)0;                        /* a(2k) = 0  for k>0 */

    /* odd index  n = 2m+1  */
    compute_A_up_to(n);                         /* need up to this n */

    seq_t val = A[n];                           /* tangent number T_m */
    idx_t m = (n - 1) >> 1;                     /* m = (n-1)/2 */

    if (m & (idx_t)1ULL)                        /* sign alternates every m */
        val = -val;

    return val;
}
